  <main v-else class="studio">
    <header class="studio-topbar"><div class="brand"><span class="brand-mark"><BookOpenCheck :size="21" /></span><span><strong>Inquiry Studio</strong><small>探究式教学工作台</small></span></div><div class="top-pills"><span class="top-pill active">教学工作台</span></div><div class="top-actions"><button v-if="designMode || workspace" @click="returnHome">返回首页</button><button @click="showHistory = !showHistory"><History :size="16" /> 历史记录</button><button @click="leave">返回对话模式</button></div></header>
